// @exec: {"yield_time_ms": 1000}
text(await tools.exec_command({cmd:`$ErrorActionPreference='Stop'
$root=(Resolve-Path .).Path
if($root -cne 'E:\\TA Projects\\EOD Charting Platform'){throw 'Wrong root'}
$old='4cf6c66ce65c6cfe76a97af8e1636dbd16e9519a'
$target='09d20595bdc2ccbb6f11320fea3caf32c606c940'
$remote=@(git ls-remote origin refs/heads/main)
if($LASTEXITCODE -or $remote.Count -ne 1 -or $remote[0] -cne "$target\`trefs/heads/main"){throw 'Remote changed'}
if((git rev-parse HEAD).Trim() -cne $old -or (git rev-parse origin/main).Trim() -cne $target -or (git branch --show-current).Trim() -cne 'main'){throw 'Local refs changed'}
git merge-base --is-ancestor $old $target
if($LASTEXITCODE){throw 'No fast-forward'}
$stamp=[DateTimeOffset]::UtcNow.ToOffset([TimeSpan]::FromMinutes(330)).ToString('yyyyMMdd_HHmmss')
$j=New-Item -ItemType Directory "tmp/EOD_GitSync_Apply_\${stamp}_IST"
$j.FullName|Set-Content tmp/eod-gitsync-apply-current.txt
$remote|Set-Content "$($j.FullName)/authority.log"
git -c core.autocrlf=false worktree add --detach "$($j.FullName)/candidate" $target *> "$($j.FullName)/worktree.log"
if($LASTEXITCODE){throw 'Worktree failed'}
@'
from pathlib import Path
import sys,re,json,subprocess,hashlib
root=Path.cwd()
j=Path(sys.argv[1]); candidate=j/'candidate'
prior=Path('tmp/EOD_GitSync_20261106_003941_IST')
rows=json.loads((prior/'inventory.json').read_text(encoding='utf-8-sig'))
def git(*a):return subprocess.check_output(['git',*a])
def h(b):return hashlib.sha256(b).hexdigest().upper()
def norm(b):return b.replace(b'\\r\\n',b'\\n')
assert len(rows)==136
assert git('status','--porcelain=v1','-z','-uall').count(b'\\0')==136
for r in rows:
    assert h((root/r['path']).read_bytes())==r['localSha256'],r['path']
scope={r['path']:r for r in rows if r['category']=='upstream-overlap-local-difference'}
assert len(scope)==11
patt=re.compile(rb'^<<<<<<< [^\\n]+\\n(.*?)^\\|{7} [^\\n]+\\n(.*?)^=======\\n(.*?)^>>>>>>> [^\\n]+\\n',re.M|re.S)
choose={'FEATURE_STATUS_MATRIX_EOD_CHARTING_PLATFORM.md':3,
        'src-tauri-shell/src/bhavcopy/parsers/csv.rs':3,
        'src/platform/tauriDesktop.ts':1}
for r in rows:
    name=r['path']; active=root/name; dest=candidate/name
    b=active.read_bytes()
    if name in scope:
        remote=git('show','origin/main:'+name)
        if name in choose:
            preview=(prior/r['conflictPreview']).read_bytes()
            assert len(patt.findall(preview))==r['previewConflicts']
            m=patt.sub(lambda match:match.group(choose[name]),preview)
        elif name.endswith('/index_fallback/tests.rs'):
            assert norm(b).startswith(norm(remote).rstrip()+b'\\n')
            m=norm(b)
        elif name.endswith('/StatusBarIstClock.test.ts'):
            needle=b"    expect(source).toContain('activeTab?.visibleBarCount ?? 0');"
            assert remote.count(needle)==1
            m=remote.replace(needle,b"""    expect(source).toContain('countVisibleBars(activeTab.viewport, activeTab.displayBars.length)');\\n    expect(source).toContain('{visibleBarCount}');""")
            assert b"snapshot?.dbStats?.dateFrom ?? '-'" in m
        else:
            base=git('show','HEAD:'+name)
            paths=[j/f'merge-{len(list(j.glob("merge-*.base")))}.{suffix}' for suffix in ('local','base','remote')]
            for f, data in zip(paths,(b,base,remote)):f.write_bytes(norm(data))
            merge=subprocess.run(['git','merge-file','-p',*map(str,paths)],capture_output=True)
            assert merge.returncode==0,(name,merge.stderr)
            m=merge.stdout
        assert not re.search(rb'(?m)^(<<<<<<< |\\|{7} |=======\\r?$|>>>>>>> )',m),name
        b=m.replace(b'\\n',b'\\r\\n') if b'\\r\\n' in b else m
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_bytes(b)
    r['previewSha256']=h(b)
    r['changedByReconciliation']=r['localSha256']!=h(b)
    if name not in scope:
        assert r['previewSha256']==r['localSha256']
(j/'preservation-plan.json').write_text(json.dumps(rows,indent=2)+'\\n')
print('PASS 136 entries, 11 scoped overlaps,',sum(r['changedByReconciliation'] for r in rows),'dirty path byte changes')
for r in rows:
    if r['path'] in scope:print(r['path'], 'changed' if r['changedByReconciliation'] else 'exact local')
'@ | Set-Content "$($j.FullName)/preview.py"
python "$($j.FullName)/preview.py" $j.FullName *> "$($j.FullName)/preview.log"
$c=$LASTEXITCODE; Get-Content "$($j.FullName)/preview.log"; if($c){throw 'Preview failed'}`,yield_time_ms:1000}))

