text(await tools.exec_command({cmd:`$ErrorActionPreference='Stop'
$j=Get-Content tmp/eod-gitsync-apply-current.txt
$candidate=(Resolve-Path "$j/candidate").Path
$approved=Get-Content 'tmp/ux13-936ac0b/Invoke-UX13-SharedCargo.ps1' -Raw
$prior=(Resolve-Path 'tmp/ux13-936ac0b/candidate').Path
if(-not $approved.Contains($prior)){throw 'Approved runner source pin missing'}
$approved.Replace($prior,$candidate)|Set-Content "$j/Invoke-Sync-SharedCargo.ps1"
$env:EOD_SYNC_SCRIPT="$j/Invoke-Sync-SharedCargo.ps1"
powershell.exe -NoProfile -Command '$tokens=$null;$errors=$null;$ast=[System.Management.Automation.Language.Parser]::ParseFile($env:EOD_SYNC_SCRIPT,[ref]$tokens,[ref]$errors);if($errors.Count){$errors;exit 1};$bad=$ast.FindAll({param($node) $node -is [System.Management.Automation.Language.IfStatementAst] -and ($node.Clauses.Count -gt 1 -or $node.ElseClause)},$true);if($bad.Count){exit 2};"PASS parser and guard clauses"' *> "$j/parser.log"
if($LASTEXITCODE){throw 'Runner parser failed'}
function Npm([string]$name,[string[]]$argsList){
 $log="$j/$name.log"
 "COMMAND: npm $($argsList -join ' ')"|Set-Content $log
 npm.cmd @argsList *>> $log
 $c=$LASTEXITCODE
 "EXIT: $c"|Add-Content $log
 Get-Content $log -Tail 9
 if($c){throw "$name failed"}
}
function CargoCheck([string]$name,[string]$action,[string[]]$argsList){
 foreach($mode in 'Preview','Run'){
   $log="$j/\${name}_$mode.log"
   try{& "$j/Invoke-Sync-SharedCargo.ps1" -Mode $mode -CargoAction $action -CargoArguments $argsList *> $log}
   catch{"FAIL: $_"|Add-Content $log;Get-Content $log -Tail 36;throw}
   $mark='BUILD01_SHARED_CARGO_COMMAND_PASS'
   if($mode -eq 'Preview'){$mark='BUILD01_SHARED_CARGO_PREVIEW_PASS_NO_BUILD_NO_CHANGES'}
   if(-not(Select-String -LiteralPath $log -SimpleMatch -Pattern $mark -Quiet)){throw "$name $mode missing pass"}
   'EXIT: 0'|Add-Content $log
   Get-Content $log -Tail 8
 }
}
Push-Location -LiteralPath $candidate
try{
 Npm 'npm-ci' @('ci','--no-audit','--no-fund')
 Npm 'vitest-focused' @('run','test','--','--reporter=verbose','src/features/bhavcopy','src/components/__tests__/BhavcopyDownloadRerun.test.ts','src/components/__tests__/StatusBarIstClock.test.ts','src/components/__tests__/BhavcopyOfficialHolidaySync.test.ts','src/components/__tests__/BhavcopyMarketHolidayRefresh.test.ts','src/components/__tests__/BhavcopyMarketHolidayLayoutStatus.test.ts','src/platform/__tests__/chartDataIntegrity.test.ts','src/components/__tests__/CommandPaletteKeyboardNavigation.test.ts','src/components/__tests__/NiftyHistoryReview.test.ts')
 Npm 'typecheck' @('run','typecheck:renderer')
 Npm 'renderer-build' @('run','build:renderer')
} finally {Pop-Location}
CargoCheck 'bhavcopy' 'test' @('bhavcopy::','--','--test-threads=1')
CargoCheck 'recovery' 'test' @('bhavcopy_recovery::','--','--test-threads=1')
CargoCheck 'locking' 'test' @('price_store_operation_lock::','--','--test-threads=1')
CargoCheck 'tauri-check' 'check' @()`,yield_time_ms:1000,max_output_tokens:2200}))

